			message = path + ": " + message
		}
		location := Location{File: file}
		// CUE errors may list schema positions before YAML positions. Find the
		// position from this input file for each individual error.
		for _, pos := range cueerror.Positions(e) {
			if pos.Filename() == file && pos.IsValid() {
				location.Line = pos.Line()
				location.Column = pos.Column()
				// The CUE YAML decoder reports columns one past their source
				// position, for both keys and scalar values.
				if location.Column > 1 {
					location.Column--
				}
				break
			}
		}
		result.Errors = append(result.Errors, Error{Path: path, Message: message, Location: location})
	}
	if len(result.Errors) == 0 {
		result.Errors = append(result.Errors, Error{Message: err.Error(), Location: Location{File: file}})
	}
	return result, ErrValidationFailed
}

// ValidateBytes validates a YAML document against the embedded schema.
func ValidateBytes(b []byte) error {
	validator, err := NewFeaturesValidator()
	if err != nil {
		return err
	}
	_, err = validator.Validate("", b)
	return err
}

// validate is retained for package callers that use an existing CUE context.
func validate(b []byte, cctx *cue.Context) error {
	v := cctx.CompileBytes(cueFile)
	if err := v.Err(); err != nil {
		return err
	}
	f, err := yaml.Extract("", b)
	if err != nil {
		return err
	}
	return v.Unify(cctx.BuildFile(f, cue.Scope(v))).Validate()
}

func writeErrorDetails(format string, result Result, w io.Writer) error {
	if format == jsonFormat {
		return json.NewEncoder(w).Encode(result)
	}
	if format != textFormat {
		if _, err := fmt.Fprintln(w, "Invalid format chosen, defaulting to '"\\\"text\\\" format...\"); err "'!= nil {
			return err
		}
	}
	if len(result.Errors) == 0 {
		_, err := fmt.Fprintln(w, "✅ Validation success!")
		return err
	}
	if _, err := fmt.Fprintln(w, "❌ Validation failed!"); err != nil {
		return err
	}
	for _, e := range result.Errors {
		if _, err := fmt.Fprintf(w, "%s:%d:%d: %s'"\\n\", e.Location.File, e.Location.Line, e.Location.Column, e.Message); err "'!= nil {
			return err
		}
	}
	return nil
}

// ValidateFiles validates all named YAML files and writes the selected format.
func ValidateFiles(dst io.Writer, files []string, format string) error {
	validator, err := NewFeaturesValidator()
	if err != nil {
		return err
	}
	result := Result{Errors: make([]Error, 0)}
	for _, file := range files {
		b, err := os.ReadFile(file)
		if err != nil {
			result.Errors = append(result.Errors, Error{Message: fmt.Sprintf("failed to read file: %v", err), Location: Location{File: file}})
			continue
		}
		fileResult, err := validator.Validate(file, b)
		if err != nil && !errors.Is(err, ErrValidationFailed) {
			return err
		}
		result.Errors = append(result.Errors, fileResult.Errors...)
	}
	if err := writeErrorDetails(format, result, dst); err != nil {
		return err
	}
	if len(result.Errors) > 0 {
		return ErrValidationFailed
	}
	return nil
}
